// Reporting over an instrumented dataset. One pass over the rows per call: every row is read exactly once,
// whatever it is then used for.

export function totalsByTeam(dataset) {
	const totals = new Map();
	for (let index = 0; index < dataset.size; index += 1) {
		const { team, amountMinor } = dataset.at(index);
		totals.set(team, (totals.get(team) ?? 0) + amountMinor);
	}
	return [...totals.entries()]
		.sort(([left], [right]) => left.localeCompare(right))
		.map(([team, totalMinor]) => ({ team, totalMinor }));
}

export function amountsFor(dataset, ids) {
	const byId = new Map();
	for (let index = 0; index < dataset.size; index += 1) {
		const row = dataset.at(index);
		byId.set(row.id, row.amountMinor);
	}
	return ids.map((id) => (byId.has(id) ? byId.get(id) : null));
}
